// Ball masses are AndyMark's listed weights. Their ratio is 1.65, and the Event Field Setup Guide needs a ratio under
// 1.667, because it states that 3 POLLEN + 3 NECTAR weigh less than 8 POLLEN. The hive ballast is calibrated against
// these masses. Restitution, friction, and damping are still estimates.
export const BALL = {
  // AndyMark's product page for the BIOBUZZ scoring elements lists POLLEN (am-5851) at 0.055 lb and NECTAR (am-5852)
  // at 0.091 lb. The Competition Manual, section 9.8, gives no weight: it says that both are Gopher ResisDent
  // polyethylene balls. scripts/ball-mass.mjs cross-checks the weights against the CAD: the NECTAR model holds 42.8 cm³
  // of plastic, which is 40.7 g at 0.95 g/cm³, and the POLLEN model holds 22.2 cm³, which is 21.0 g.
  pollenMass: 0.055 * 0.45359237, // 24.9 g
  nectarMass: 0.091 * 0.45359237, // 41.3 g
  restitution: 0.45,
  friction: 0.6,
  linearDamping: 0.12,
  angularDamping: 1.2,
  airDensity: 1.2, dragCd: 0.47,
};

// Hive dynamics. `comHeight` is the ballast-washer equivalent: it sets the
// tipping point. test/hive-calibration.test.ts checks the value against the
// six rows of Event Field Setup Guide section 12.3.
export const HIVE_DYN = {
  mass: 1.4,
  inertia: 0.16,          // About the pivot axis, kg m^2
  comHeight: 0.063,       // Calibrated with the AndyMark ball masses: 0.060 to 0.066 passes all six rows. See docs/hive-calibration.md.
  pivotFriction: 0.012,   // Coulomb friction torque, N m
  damperZone: 0.14,       // The damper engages within this angle of a stop, rad
  damperCoeff: 0.9,       // N m s per rad while closing on a stop
};

export type ShooterType = 'catapult' | 'fifo' | 'dual';
export interface Dist { mean: number; std: number }
export interface LaunchParams {
  offset: [number, number, number]; // Launch point in the robot frame: forward, left, up. Meters.
  elevationDeg: Dist;
  speed: Dist;                      // m/s
  yawStdDeg: number;
  backspinRpm: Dist;
}
export interface RobotConfig {
  length: number; width: number; height: number; mass: number; yawInertia: number;
  wheelRadius: number; halfWheelbase: number; halfTrack: number;
  motor: { freeRpm: number; stallTorque: number; stallCurrent: number; freeCurrent: number };
  battery: { openCircuitV: number; resistance: number };
  gearEfficiency: number; strafeEfficiency: number; wheelMu: number; rollingResistance: number; viscousLoss: number;
  capacity: number;
  /** `dualSided` adds a second intake on the rear face, so the robot collects floor elements from either end. Default: false. POLLEN still comes out of a FLOWER at the front only. */
  intake: { width: number; reach: number; successP: number; retrySec: number; flowerReach: number; flowerPeriodSec: number; dualSided?: boolean };
  /** `facing: 'rear'` launches out of the side opposite the intake, so the robot turns less between pickup and launch. */
  /**
   * `dualSided` lets the robot launch out of either end, for example with a two-position turret or two catapults. It
   * launches out of the end that faces its own HIVE. Default: false.
   * `turret` mounts the shooter on a turret with full range of motion and an instant slew: each launch aims at the
   * raised CELL's mouth of the robot's own HIVE, whatever the robot's heading. It's an upper bound: a real turret has
   * limits, so it can only do worse. It overrides `dualSided` and `facing`. Default: false.
   */
  shooter: { type: ShooterType; facing: 'front' | 'rear'; cycleSec: number; pollen: LaunchParams; nectar: LaunchParams; dualSided?: boolean; turret?: boolean };
  place: { range: number; maxBearingDeg: number; durationSec: number; successP: number };
  /**
   * The AprilTag camera. It faces the same side as the shooter and looks up at the underside of the raised CELL.
   * `offset` is forward, left, up in meters, with forward measured toward the shooter side.
   */
  camera: { offset: [number, number, number]; pitchDeg: number; hFovDeg: number; vFovDeg: number; maxRange: number; maxIncidenceDeg: number };
}

