/**
 * Sets the drive motor's free speed by changing the gear ratio of the same motor: the stall torque scales inversely.
 * The reference is the goBILDA 5203 at 435 rpm and 1.834 N m (goBILDA spec sheet).
 */
export function setDriveRpm(c: RobotConfig, rpm: number) { c.motor.freeRpm = rpm; c.motor.stallTorque = (DEFAULT_ROBOT.motor.stallTorque * DEFAULT_ROBOT.motor.freeRpm) / rpm; }
/** Sets the robot mass in kilograms and scales the yaw inertia with it. R102 limits a robot to 42 lb (19.05 kg). Call it after `setSquareSize`. */
export function setMass(c: RobotConfig, kg: number) { c.yawInertia *= kg / c.mass; c.mass = kg; }
/** Sets a square chassis size in meters and scales the wheelbase, the track, the intake width, and the yaw inertia with it. R101 limits a robot to 18 in. (0.457 m). */
export function setSquareSize(c: RobotConfig, m: number) { const k = m / DEFAULT_ROBOT.length; c.length = c.width = m; c.halfWheelbase = DEFAULT_ROBOT.halfWheelbase * k; c.halfTrack = DEFAULT_ROBOT.halfTrack * k; c.intake.width = m - 0.09; c.yawInertia = DEFAULT_ROBOT.yawInertia * k * k; }

// Load in the raised CELL, in POLLEN equivalents, at which the HIVE tips. It follows from the calibration
// standard with NECTAR at 1.65, the ratio of the listed masses: 7 POLLEN (7.0) and 3 NECTAR + 2 POLLEN (6.95) hold; 3 NECTAR + 3 POLLEN (7.95) tips.
export const TIP_LOAD = { threshold: 7.4, pollen: 1, nectar: 1.65 };

